B.We=new A.Z(B.w,["Nova City. Uma cidade onde humanos e rob\xf4s vivem juntos, em paz... tudo gra\xe7as \xe0 energia do N\xfacleo Nova.","Nova City. A city where humans and robots live together in peace... all thanks to the energy of the Nova Core.","Nova City. Una ciudad donde humanos y robots viven juntos, en paz... todo gracias a la energ\xeda del N\xfacleo Nova."],t.w)
B.alZ=new A.e9(null,B.We,null)
B.Wc=new A.Z(B.w,["Olha s\xf3 esse c\xe9u! Dia perfeito pra treinar. Nada pode estragar isso... n\xe9, Zek?","Look at that sky! A perfect day to train. Nothing can ruin this... right, Zek?","\xa1Mira ese cielo! Un d\xeda perfecto para entrenar. Nada puede arruinarlo... \xbfverdad, Zek?"],t.w)
B.alQ=new A.e9("kael",B.Wc,"happy")
B.W4=new A.Z(B.w,["Ai, n\xe3o! Por que voc\xea foi falar isso, Kael? Toda vez que algu\xe9m fala isso, d\xe1 tudo errado!","Oh, no! Why did you say that, Kael? Every time someone says that, everything goes wrong!","\xa1Ay, no! \xbfPor qu\xe9 dijiste eso, Kael? \xa1Cada vez que alguien lo dice, todo sale mal!"],t.w)
B.am_=new A.e9("zek",B.W4,"scared")
B.VV=new A.Z(B.w,["Relaxa, Zek! O que poderia acontecer?","Relax, Zek! What could possibly happen?","\xa1Tranquilo, Zek! \xbfQu\xe9 podr\xeda pasar?"],t.w)
B.alO=new A.e9("kael",B.VV,"happy")
B.T2=s([B.alZ,B.alQ,B.am_,B.alO],t.tG)
B.am5=new A.lK("intro_1.jpg",1.05,1.18,B.dQ,B.eW,B.T2)
B.Wx=new A.Z(B.w,["Gente... olhem pra cima! O sol... est\xe1 sumindo!","Guys... look up! The sun... is disappearing!","Chicos... \xa1miren arriba! El sol... \xa1est\xe1 desapareciendo!"],t.w)
B.alT=new A.e9("luna",B.Wx,"scared")
B.Wq=new A.Z(B.w,["Que coisa gigante \xe9 aquela?! Parece um castelo voando!","What is that giant thing?! It looks like a flying castle!","\xbf\xa1Qu\xe9 es esa cosa gigante!? \xa1Parece un castillo volando!"],t.w)
B.alU=new A.e9("mira",B.Wq,"shocked")
B.W2=new A.Z(B.w,["Durante o eclipse, uma fortaleza sombria surgiu no c\xe9u: a Cidadela Eclipse.","During the eclipse, a dark fortress rose in the sky: the Eclipse Citadel.","Durante el eclipse, una fortaleza oscura apareci\xf3 en el cielo: la Ciudadela Eclipse."],t.w)
B.alY=new A.e9(null,B.W2,null)
B.Qy=s([B.alT,B.alU,B.alY],t.tG)
B.am2=new A.lK("intro_2.jpg",1.05,1.18,B.br,B.aY,B.Qy)
B.Wd=new A.Z(B.w,["Ha ha ha ha! Povo de Nova City... a energia do N\xfacleo Nova agora pertence a MIM!","Ha ha ha ha! People of Nova City... the energy of the Nova Core now belongs to ME!","\xa1Ja ja ja ja! Pueblo de Nova City... \xa1la energ\xeda del N\xfacleo Nova ahora me pertenece a M\xcd!"],t.w)
B.alL=new A.e9("emperor",B.Wd,"laugh")
B.Wf=new A.Z(B.w,["Meus nove chefes v\xe3o guard\xe1-la pelo mundo inteiro. E voc\xeas, heroizinhos... v\xe3o passar uma temporada nas minhas c\xe1psulas!","My nine bosses will guard it all over the world. And you, little heroes... will spend some time in my capsules!","Mis nueve jefes la guardar\xe1n por todo el mundo. Y ustedes, hero\xedtos... \xa1pasar\xe1n una temporada en mis c\xe1psulas!"],t.w)
B.alM=new A.e9("emperor",B.Wf,null)
B.VX=new A.Z(B.w,["Isso \xe9 o que voc\xea pensa!","That's what you think!","\xa1Eso es lo que t\xfa crees!"],t.w)
B.alP=new A.e9("kael",B.VX,"angry")
B.QO=s([B.alL,B.alM,B.alP],t.tG)
B.am3=new A.lK("intro_3.jpg",1.25,1.05,B.k,B.k,B.QO)
B.VZ=new A.Z(B.w,["Num instante, Luna, Mira, Zek e Nex foram levados... e trancados em c\xe1psulas, escondidas nas terras dos nove chefes.","In an instant, Luna, Mira, Zek and Nex were taken... and locked in capsules, hidden in the lands of the nine bosses.","En un instante, Luna, Mira, Zek y Nex fueron llevados... y encerrados en c\xe1psulas, escondidas en las tierras de los nueve jefes."],t.w)
B.alX=new A.e9(null,B.VZ,null)
B.WB=new A.Z(B.w,["N\xc3\xc3\xc3O! Pessoal!! Aguentem firme... eu juro que vou achar cada um de voc\xeas!","NOOO! Guys!! Hang in there... I swear I'll find every one of you!","\xa1NOOO! \xa1\xa1Chicos!! Aguanten... \xa1les juro que los voy a encontrar a todos!"],t.w)
B.alS=new A.e9("kael",B.WB,"desperate")
B.Sj=s([B.alX,B.alS],t.tG)
B.am0=new A.lK("intro_4.jpg",1.05,1.18,B.eW,B.dQ,B.Sj)
B.VO=new A.Z(B.w,["Kael... est\xe1 me ouvindo? Estou falando com voc\xea pela energia do vazio.","Kael... can you hear me? I'm talking to you through the void energy.","Kael... \xbfme oyes? Te hablo a trav\xe9s de la energ\xeda del vac\xedo."],t.w)
B.alV=new A.e9("nex",B.VO,null)
B.Wu=new A.Z(B.w,["As c\xe1psulas est\xe3o bem escondidas. Procure em cada canto... e cuidado com os chefes.","The capsules are well hidden. Search every corner... and watch out for the bosses.","Las c\xe1psulas est\xe1n bien escondidas. Busca en cada rinc\xf3n... y cuidado con los jefes."],t.w)
B.alW=new A.e9("nex",B.Wu,null)
